// Build the request for OUR ffmpeg assemble endpoint (Railway). The server
// measures each clip itself and silence-pads every voiceover to its scene's
// exact video length; aspect picks the output canvas.
const clips = $('Prepare Clips').all();
if (!clips.length) throw new Error('No clips to assemble.');
const sceneChapters = clips.map(c => c.json.chapter || 0);

// Aspect resolution order: trigger input -> webhook body -> project field
// -> 16:9. Reading a nonexistent Airtable field is safely undefined.
let trig = {};
try { if ($('Receive Project ID').isExecuted) trig = $('Receive Project ID').first().json; } catch (e) {}
try { if (!trig.Aspect && $('Normalize Assemble Input').isExecuted) trig = $('Normalize Assemble Input').first().json; } catch (e) {}
const pf = ($('Fetch Project Info').first().json.fields) || {};
const aspect = (trig.Aspect === '9:16' || pf['Format'] === '9:16') ? '9:16' : '16:9';

let opts = {};
try { opts = JSON.parse(pf['Editing Options'] || '{}') || {}; } catch (e) {}

// TWO independent switches, both sent explicitly — the server's implicit
// defaults must never decide this.
//
// sfx: the Scene Final URL clips are RAW Veo output, so their audio track is
// Veo's generated ambience (the submit prompt bans speech and music, leaving
// natural sound effects only). ON → mixed at SFX_LEVEL under the narration,
// sidechain-ducked server-side so narration stays predominant. Default ON:
// silent footage under a voice sounds dead.
//
// SFX_LEVEL was 0.25 and judged too subtle on a real SFX-only render
// (Warhammer, 2026-08-10) — audible only in headphones, in the gaps. 0.35
// lifts the effects without touching the ducking, so the voice still wins
// whenever it speaks. It is now the DEFAULT rather than the only value: the
// brief's SFX row carries a volume slider, stored as Editing Options.sfxLevel,
// and a film that wants more or less says so. Refuses rather than guesses —
// out of range or unparseable falls back here, so a bad value can never reach
// the mixer. The same rule lives in platform/lib/data/derive.ts and in the
// orchestrator's 'Normalize Webhook Input'; change one, change all three.
const SFX_LEVEL = 0.35;
const sfxOn = opts.sfx !== false;
const sfxLevel = (() => {
  const n = Number(opts.sfxLevel);
  return (Number.isFinite(n) && n >= 0.05 && n <= 1) ? Math.round(n * 100) / 100 : SFX_LEVEL;
})();

// music: a background track from the Drive 'Muzica' folder AND the
// synthesized boom/whoosh/riser accents at hook, chapter cuts and end
// screen. Neither comes from the scene — both are composed here — so they
// share one opt-IN switch. The accents used to play unconditionally, which
// is how a film ended up carrying music unrelated to its footage.
const musicOn = opts.music === true;
let musicUrl;
if (musicOn) {
  try { musicUrl = $('Pick Music Track').first().json.url || undefined; } catch (e) {}
}
// How loud that track sits under the voice. 0.22 is the gain assemble.mjs
// hard-coded for the music bed until the brief's Music row grew a slider
// (stored as Editing Options.musicLevel), so absence is today's sound. Same
// refusal rule as sfxLevel above — three copies: platform/lib/data/derive.ts,
// the orchestrator's Normalize Webhook Input, and here. The accents at the
// cuts are not scaled by it; they are moments, not a bed.
const MUSIC_LEVEL = 0.22;
const musicLevel = (() => {
  const n = Number(opts.musicLevel);
  return (Number.isFinite(n) && n >= 0.05 && n <= 1) ? Math.round(n * 100) / 100 : MUSIC_LEVEL;
})();

// The canvas this film is built on. 720p unless the project says otherwise,
// and only /upscale-film says otherwise — because a 1080p montage made of
// 720p clips buys bytes and nothing else. It is emitted at the top level too,
// so Submit Graphics and Graphics Guard read the SAME value rather than
// deriving it again: the montage and the graphics drawn over it must agree on
// the canvas, and the poll ceiling has to know the render costs 2.09x.
const resolution = opts.resolution === '1080p' ? '1080p' : '720p';

// The gap between the end of a scene's narration and the cut to the next
// scene. 0.35s for every category — the montage's classic breath — except
// Kids story, whose narration_pace asks for real pauses so young listeners
// can follow (relaxed 0.8s, read-along 1.2s, in film time: the whole-film
// retime then stretches those too). /assemble clamps to [0.2, 2] and falls
// back to 0.35, so a malformed value cannot stall the film.
const sceneGap = (() => {
  if (opts.category !== 'kids') return 0.35;
  return String((opts.categoryOptions || {}).narration_pace || '') === 'very_slow' ? 1.2 : 0.8;
})();

// The HOOK (2026-09-11). A film written by the hook system carries
// Editing Options.hookPlan, and its chapter-0 scenes are TEASER SHOTS: three
// seconds each (six for a slate), cut on the last word rather than a breath
// after it, and silent for the slate/action/cliffhanger styles — where the
// clip's length is the plan's, not the narration's. /assemble reads these
// per-scene keys and clamps each; a film with no plan (everything made before
// this) sends none and times exactly as it always has. The riser is asked for
// only by the two styles whose whole point is tension breaking on the cut.
const hookPlan = (opts.hookPlan && typeof opts.hookPlan === 'object') ? opts.hookPlan : null;
const scenes = clips.map(c => {
  const s = {
    videoUrl: c.json.url,
    audioUrl: (c.json.voiceUrl && c.json.voiceUrl.startsWith('http')) ? c.json.voiceUrl : undefined,
  };
  if (hookPlan && (c.json.chapter || 0) === 0) {
    const planned = Number(c.json.seconds);
    s.holdSeconds = (Number.isFinite(planned) && planned > 0) ? Math.min(20, Math.max(1.5, planned)) : 3;
    s.minSeconds = 1.6;
    // The breath after a SPOKEN teaser beat. It was 0.12s, chosen to make the
    // picture cut hard on the last word — right for the shot, wrong for the
    // voice, and the two were given the same number. A beat is a whole
    // statement, and the breath trim has already cut the take's own silence
    // off both ends, so at 0.12 four statements arrive butted together with
    // less air between them than the narrator leaves between two clauses of
    // one sentence. The producer heard it as the hook being read too fast to
    // follow. 0.45 is MORE than an ordinary scene's 0.35: a teaser line has to
    // land on its own, which is the whole reason it is a separate shot. Silent
    // shots are untouched — they are held for holdSeconds and have no voice to
    // give room to.
    s.gapSeconds = 0.45;
  }
  return s;
});
// THE CLOSING HOLD (2026-09-16). The last scene used to end 0.35s after the
// last word, then the flash and the end screen — the montage's classic breath,
// right between two scenes and wrong after the last one, where it is what the
// producer hears as the film "stopping". On a Story the last picture now holds
// 1.5s after its narration, 2s on a Kids story (whose listeners are slower);
// documentary and cinematic keep the classic cut. Applied to the LAST VOICED
// scene — a silent tail shot has no narration to hold after — through the
// per-scene gapSeconds /assemble already clamps to [0, 2]. An absent category
// is a Story, the site's default, so films made before categories existed get
// the hold too when they are re-rendered.
const closingCategory = (opts.category === undefined || opts.category === '' ) ? 'story' : String(opts.category);
const closingHold = closingCategory === 'kids' ? 2 : closingCategory === 'story' ? 1.5 : null;
if (closingHold !== null) {
  for (let i = scenes.length - 1; i >= 0; i--) {
    if (scenes[i].audioUrl) { scenes[i].gapSeconds = closingHold; break; }
  }
}
const hookRiser = !!hookPlan && ['cliffhanger', 'action'].includes(String(hookPlan.style || ''));

return [{ json: { body: {
  scenes,
  sceneChapters,
  hookRiser,
  musicUrl,
  musicVolume: musicOn ? musicLevel : undefined,
  aspect,
  resolution,
  nativeAudio: sfxOn ? sfxLevel : false,
  stingers: musicOn,
  sceneGap,
}, resolution, sceneCount: scenes.length, tone: pf.Tonalitate || 'default', aspect, musicUrl: musicUrl || null, sfx: sfxOn, sfxLevel: sfxOn ? sfxLevel : 0, music: musicOn, musicLevel: musicOn ? musicLevel : 0 } }];

const j = $input.first().json;
// A mid-render Railway deploy replaces the container and wipes the
// in-memory job map: the poll answers 404 'job not found' although nothing
// was wrong with the job. The work died with the container, so the only
// recovery is resubmitting — flagged here, routed by 'Render Lost?'.
const httpErr = j.error && typeof j.error === 'object' ? String(j.error.message || j.error.description || '') : (typeof j.error === 'string' && !j.status ? j.error : '');
// 720 polls x 5s = 60 minutes. It was 15 (180 polls) while a film was a
// handful of scenes; a 71-scene film is 142 downloads, 71 breath trims and
// an eight-minute encode, and the ceiling has to be sized for the longest
// film the brief allows (12 minutes), not the shortest. 'Wait Render'
// sleeps 5s BEFORE the first check (measured on 3599: a one-scene ffmpeg
// finished well inside the old 20s and n8n slept all of it). Any change to
// the Wait node has to move this number by the same factor or the ceiling
// moves with it.
const MAX_POLLS = 720;
if (/not.*found|404/i.test(httpErr)) {
  if ($runIndex > MAX_POLLS) throw new Error('assemble job lost repeatedly (' + $runIndex + ' polls) — giving up.');
  return [{ json: { lost: true, status: 'lost' } }];
}
const s = (j.status || '').toLowerCase();
if (s === 'error') {
  throw new Error('assemble failed: ' + (j.error || 'unknown'));
}
if ($runIndex > MAX_POLLS) {
  throw new Error('assemble timed out after ' + $runIndex + ' polls. Last status: ' + s);
}
return [{ json: Object.assign({ lost: false }, j) }];

let scenes = $input.all().slice();
const seen = new Set();
scenes = scenes.filter(s => { const id = s.json.id; if (!id || seen.has(id)) return false; seen.add(id); return true; });
scenes = scenes.filter(s => { const v = (s.json.fields || {})['Scene Final URL'] || ''; return v.startsWith('http'); });
const ord = it => { const f = it.json.fields || {}; return (typeof f['Ordine Scenă'] === 'number') ? f['Ordine Scenă'] : null; };
scenes.sort((a, b) => {
  const oa = ord(a), ob = ord(b);
  if (oa !== null && ob !== null && oa !== ob) return oa - ob;
  const t = new Date(a.json.createdTime) - new Date(b.json.createdTime);
  if (t) return t;
  return a.json.id < b.json.id ? -1 : 1;
});
if (!scenes.length) throw new Error('No scenes with a final muxed clip (Scene Final URL) found for this project.');
return scenes.map((s, i) => {
  const o = ord(s);
  // Ordine Scenă = chapter*100 + scene (hook = 1 → chapter 0).
  const chapter = o !== null ? Math.floor(o / 100) : (i === 0 ? 0 : 1);
  return { json: {
    id: s.json.id,
    url: s.json.fields['Scene Final URL'],
    voiceUrl: s.json.fields['Voiceover URL'] || '',
    // Same strip as both TTS paths: speaker tags ([NARRATOR], [CHARACTER: X])
    // are routing, not narration — without this they showed up in captions.
    narratorText: String(s.json.fields['Script Scenă'] || '').replace(/\[[^\]]{0,60}\]\s*/g, ' ').replace(/\s+/g, ' ').trim(),
    chapter,
    order: o,
    // The planned length (3 or 6 on a hook shot, 8 elsewhere). Only the hook
    // reads it — Build Timeline turns it into holdSeconds for a silent shot.
    seconds: (typeof s.json.fields['Durată Scenă (secunde)'] === 'number') ? s.json.fields['Durată Scenă (secunde)'] : null,
  } };
});

// Website/manual retrigger path: accept {Project_ID, aspect?, captions?} in
// the POST body and hand downstream the same shape the sub-workflow trigger
// gives.
const b = $json.body || {};
const id = b.Project_ID || b.project_id || '';
if (!id) throw new Error('Project_ID missing in webhook body');
return [{ json: {
  Project_ID: id,
  Aspect: b.aspect === '9:16' ? '9:16' : (b.aspect || ''),
  No_Captions: (b.captions === 'no' || b.no_captions === true) ? 'yes' : '',
} }];

// Diagnostic harness (draft only): route a metadata or compose request
// through the existing fal-credentialed nodes.
const b = $json.body || {};
if (b.mode === 'compose') return [{ json: { body: b.compose } }];
return [{ json: { url: b.media_url } }];

const driveId = $('Upload Final To Drive').first().json.id;
return [{ json: {
  video_url: 'https://drive.google.com/uc?export=download&id=' + driveId,
  verify: $('Render Guard').last().json.verify || null,
} }];

// Graphics pass: hook title, chapter markers, transitions, captions,
// grade and end screen over the ffmpeg-assembled video. Scene timings and
// real narration lengths come from the assemble step's own ffprobe
// verification, so captions pace with the actual voice.
const status = $('Render Guard').last().json; // {outputUrl, verify}
if (!status.outputUrl) throw new Error('assemble outputUrl missing');
const clips = $('Prepare Clips').all();
const v = status.verify || {};
const starts = v.sceneStartsSeconds || [];
const voices = v.voiceDurationsSeconds || [];
const total = v.videoSeconds || 0;
const scenes = clips.map((c, i) => {
  const start = starts[i] ?? (i * 8);
  const end = (i + 1 < starts.length) ? starts[i + 1] : total;
  return {
    narratorText: c.json.narratorText || '',
    startSeconds: start,
    durationSeconds: Math.max(0.5, end - start),
    chapter: c.json.chapter || 0,
    speechSeconds: voices[i] || undefined,
  };
});
const pf = $('Fetch Project Info').first().json.fields || {};

// Aspect + captions: trigger input -> webhook body -> project fields -> defaults.
let trig = {};
try { if ($('Receive Project ID').isExecuted) trig = $('Receive Project ID').first().json; } catch (e) {}
try { if (!trig.Aspect && !trig.No_Captions && $('Normalize Assemble Input').isExecuted) trig = $('Normalize Assemble Input').first().json; } catch (e) {}
const aspectRatio = (trig.Aspect === '9:16' || pf['Format'] === '9:16') ? '9:16' : '16:9';

// Per-overlay toggles chosen in the site form, stored as JSON on the
// project ('Editing Options'). Missing field/old projects = everything on.
let opts = {};
try { opts = JSON.parse(pf['Editing Options'] || '{}') || {}; } catch (e) { opts = {}; }

// How hard the montage re-frames across a cut. 0 holds ONE framing for the
// whole film; 1 and 2 contrast the framing at every scene boundary.
//
// Sent explicitly, and defaulting to 0, because omitting it made Remotion
// derive it from the tone's editing energy - which is 1 for most tones, so
// every film got the contrast whether it suited the footage or not. Measured
// on a 15-scene dialogue film: scale jumps of 0.075 to 0.135 plus a position
// shift, on all 14 boundaries. The planner is blind to the footage, and the
// contrast only reads as a new shot when consecutive scenes actually look
// different. On a two-hander every scene is the same two people in the same
// place, so it reads as a zoom of the same shot - reported three times as a
// zoom bug, and it was never a bug, it was this setting.
//
// Still a button, not a decision: a project that wants the contrast back sets
// montageIntensity in its Editing Options.
const montageIntensity = [0, 1, 2].includes(opts.montageIntensity) ? opts.montageIntensity : 0;

// A cinematic (silent) project's Script Scenă is an unspoken shot note, not
// narration. THREE surfaces read that field as if it were spoken, and each
// one puts the beat sheet on screen: captions print it, the chapter card
// borrows its first eight words when the chapter has no title of its own,
// and a text card lifts figures out of it (a year or a duration in a stage
// direction reads to the pattern exactly like a fact the narration speaks).
// Captions were the only one visible to the producer, which is how the other
// two survived. One flag now tells the render, and all three read it.
const narrationIsSpoken = opts.category !== 'cinematic';
const showCaptions = !(trig.No_Captions === 'yes' || pf['Fără Subtitrări'] === true) && narrationIsSpoken;

// Real chapter titles from the linked script's [CHAPTER n: title] markers.
const chapterTitles = {};
try {
  const sc = ($('Fetch Script Titles').first().json.fields || {})['Script Content'] || '';
  const re = /\[CHAPTER\s+(\d+)\s*:\s*([^\]]+)\]/g;
  let m;
  while ((m = re.exec(sc))) chapterTitles[m[1]] = m[2].trim();
} catch (e) {}

return [{ json: { body: {
  finalVideoUrl: status.outputUrl,
  projectTitle: pf['Nume Proiect'] || 'Video Factory',
  scenes,
  tone: pf['Tonalitate'] || 'Dark',
  channelName: 'Video Factory',
  aspectRatio,
  showCaptions,
  narrationIsSpoken,
  montageIntensity,
  // The cold open Scripting planned (style, beats, the one card its style
  // may draw). The render reads it defensively and a film without one opens
  // on its footage. The old showHookTitle switch is retired: the opening
  // title card is gone, replaced by the teaser (src/hook.ts).
  hookPlan: (opts.hookPlan && typeof opts.hookPlan === 'object') ? opts.hookPlan : undefined,
  showChapterCards: opts.chapterCards !== false,
  // The producer's "drawn cards" switch, which until now silenced only HALF of
  // what it names. It gates the motif chain in Scripting and `Attach Motif
  // Cards` here — but the render DERIVES its own cards from the narration when
  // no explicit `textCards` arrive, and that derivation was never gated by
  // anything. So a film with the switch off still drew a figure card: a year,
  // set large, in the middle of the frame. Measured 2026-09-12 across the 18
  // most recent films — seventeen carried no motif card at all, six of them
  // because the switch was off — which is why every one of them showed the
  // same year card and the producer reported "pe absolut fiecare videoclip
  // este aceeasi animatie". Off now means no cards of any kind, and it takes
  // effect on films already made, with no re-scripting. Absent still means on.
  showTextCards: opts.drawnCards !== false,
  showEndScreen: opts.endScreen !== false,
  chapterTitles,
} } }];

const j = $input.first().json;
// Same deploy-wipes-the-job recovery as Render Guard: 404 from the status
// poll means the container restarted mid-render, not that the render broke.
const httpErr = j.error && typeof j.error === 'object' ? String(j.error.message || j.error.description || '') : (typeof j.error === 'string' && !j.status ? j.error : '');
// The Remotion pass is headless Chrome on software GL at concurrency 1 —
// measured at ~2 frames a second (CLAUDE.md, "where a final assembly's
// minutes actually go"). A 60s film is ~1800 frames and 15 minutes; an
// 8-minute film is ~11,500 frames and ~95 minutes; the 12-minute brief is
// ~2.5 hours. The old cap of 360 polls (30 min) was sized for short films
// and would have killed every long one at the half-hour mark with a
// "timed out" that reads as a hang. 2160 polls x 5s = 3 hours. Move the
// Wait node and this number moves with it, or the ceiling silently shrinks.
// Doubled for a 1080p render, because that is what 1080p costs: 2.09x the
// time per frame (measured, 0.107s against 0.224s), which puts an eight-minute
// film at roughly 3.3 hours — past the three-hour ceiling this constant was
// raised to on 2 September. A film that renders slower than the guard allows
// does not fail slowly, it fails at the cap and reads as a hang.
const hd = (() => {
  try { return $('Build Timeline').first().json.resolution === '1080p'; } catch (e) { return false; }
})();
const MAX_POLLS = hd ? 4320 : 2160;
if (/not.*found|404/i.test(httpErr)) {
  if ($runIndex > MAX_POLLS) throw new Error('graphics job lost repeatedly (' + $runIndex + ' polls) — giving up.');
  return [{ json: { lost: true, status: 'lost' } }];
}
const s = (j.status || '').toLowerCase();
if (s === 'error') throw new Error('Remotion render failed: ' + (j.error || 'unknown'));
if ($runIndex > MAX_POLLS) throw new Error('Remotion render timed out after ' + $runIndex + ' polls. Last status: ' + s + ' progress: ' + (j.progress || 0));
return [{ json: Object.assign({ lost: false }, j) }];

// Track selection order:
//   0. a track PINNED by the producer (Editing Options.musicTrack) wins outright
//   1. files inside the tone-matched subfolder (Muzica/Dark, Muzica/Default...)
//   2. loose files in Muzica whose NAME contains the tone (dark-1.mp3)
//   3. loose files named default*
//   4. any loose file
// Multiple candidates -> random pick, so repeat videos vary.
const norm = (s) => String(s || '').toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g, '');
const isFile = (f) => f && f.id && !(f.mimeType || '').includes('folder');
// 0: the producer chose a specific track on the site (MusicPicker). The id is
// a Drive file id already shared anyone-with-link by the share-music webhook,
// so the same Railway proxy URL works for it as for every auto-picked track.
try {
  const opts = JSON.parse($('Fetch Project Info').first().json.fields['Editing Options'] || '{}') || {};
  const pinned = opts.musicTrack;
  if (pinned && typeof pinned.id === 'string' && pinned.id.trim()) {
    const id = pinned.id.trim();
    return [{ json: { id, name: String(pinned.name || id), matched: 'pinned', url: 'https://n8n-production-55dd.up.railway.app/media?id=' + id } }];
  }
} catch (e) {}
let tone = 'default';
try { tone = norm($('Fetch Project Info').first().json.fields.Tonalitate); } catch (e) {}
let subFiles = [];
try { subFiles = ($input.first().json.files || []).filter(isFile); } catch (e) {}
let rootFiles = [];
try { rootFiles = ($('List Music').first().json.files || []).filter(isFile); } catch (e) {}
const byTone = rootFiles.filter(f => norm(f.name).includes(tone));
const byDefault = rootFiles.filter(f => norm(f.name).includes('default'));
const pool = subFiles.length ? subFiles : (byTone.length ? byTone : (byDefault.length ? byDefault : rootFiles));
if (!pool.length) return [{ json: { url: null, name: null, reason: 'no tracks in Muzica folder' } }];
const t = pool[Math.floor(Math.random() * pool.length)];
// Served through our Railway media proxy so ffmpeg gets a real audio
// stream (Drive's direct links answer with redirects/HTML).
return [{ json: { id: t.id, name: t.name, matched: subFiles.length ? 'subfolder' : (byTone.length ? 'tone-name' : (byDefault.length ? 'default' : 'any')), url: 'https://n8n-production-55dd.up.railway.app/media?id=' + t.id } }];

// Subfolder-per-tone layout: Muzica/Dark, Muzica/Epic, ... If a subfolder
// matches the project's Tonalitate (or 'Default' as fallback), its files
// are preferred over loose files in the root.
const norm = (s) => String(s || '').toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g, '');
let tone = 'default';
try { tone = norm($('Fetch Project Info').first().json.fields.Tonalitate); } catch (e) {}
let folders = [];
try { folders = ($input.first().json.files || []).filter(f => (f.mimeType || '').includes('folder')); } catch (e) {}
const hit = folders.find(f => norm(f.name).includes(tone)) || folders.find(f => norm(f.name).includes('default')) || null;
return [{ json: { folderId: hit ? hit.id : null, folderName: hit ? hit.name : null } }];

// Motif cards chosen by Claude Scripting and validated THERE, where the whole
// story was known and a quote could still be checked against its scene. This
// is a lookup: nothing is re-judged on the render path.
const body = $json.body;

let opts = {};
try {
  opts = JSON.parse(($('Fetch Project Info').first().json.fields || {})['Editing Options'] || '{}') || {};
} catch (e) { opts = {}; }
// The producer's permission, checked HERE and not only where the cards are
// chosen: Final touches can switch them off long after Scripting stored them,
// so the render is the last place that can still refuse. Absent means yes —
// every film made before the switch existed keeps its cards.
const allowed = opts.drawnCards !== false;
const cards = allowed && Array.isArray(opts.motifCards) ? opts.motifCards : [];

if (cards.length) {
  // Ordine Scenă per scene id, from the node that still has both.
  const orderById = new Map();
  try {
    for (const it of $('Fetch Approved Scenes').all()) {
      const f = it.json.fields || {};
      if (it.json.id != null) orderById.set(it.json.id, f['Ordine Scenă']);
    }
  } catch (e) {}
  // The rendered scene list, in its own order, expressed as those numbers.
  const rendered = $('Prepare Clips').all().map((c) => orderById.get(c.json.id));

  const out = [];
  for (const card of cards) {
    const i = (card.sceneOrder !== undefined && card.sceneOrder !== null)
      ? rendered.indexOf(card.sceneOrder)
      : card.sceneIndex;
    // A card whose scene never got a clip is left out. Not a failure to
    // report: the scene is not in the film either.
    if (!(i >= 0 && i < (body.scenes || []).length)) continue;
    const spec = Object.assign({}, card);
    // Bookkeeping for the producer's panel, not for the renderer.
    delete spec.sceneOrder;
    delete spec.verdict;
    delete spec.why;
    spec.sceneIndex = i;
    out.push(spec);
  }
  // Only when there is one: an empty array still counts as "explicit cards"
  // downstream and would switch the derived ones off for nothing.
  if (out.length) body.textCards = out;
}

return [{ json: { body } }];

// The colour a spoken caption word is painted, chosen per film on the brief
// or in Final touches and stored as Editing Options.captionColor.
//
// Its OWN node rather than a line inside Build Remotion Props: that node is
// large and actively edited by several people, and this needs nothing from it
// but the body it already produced. Same reason Attach Motif Cards is its own
// node beside it.
//
// Absent means the white default, and that is a real decision rather than a
// missing one: white with the spoken word marked by BRIGHTNESS is the only
// accent that reads on every kind of footage — one that sits well on a night
// dock is wrong on snow. Every film used to come out amber because this prop
// defaulted to palette.primary and nothing ever set it.
//
// resolveCaptionAccent() in remotion/src/captionColor.ts has the final say and
// additionally lifts a too-dark accent toward white until it clears a
// luminance floor, because captions carry a heavy drop shadow and a deep
// colour disappears into its own shadow. The check here only keeps a
// malformed stored value from reaching the props at all.
const body = $json.body;

let opts = {};
try {
  opts = JSON.parse(($('Fetch Project Info').first().json.fields || {})['Editing Options'] || '{}') || {};
} catch (e) { opts = {}; }

const raw = String(opts.captionColor || '').trim();
if (raw && !/^(none|white|off)$/i.test(raw)) {
  const m = /^#?([0-9a-f]{3}|[0-9a-f]{6})$/i.exec(raw);
  if (m) {
    const h = m[1].length === 3 ? m[1].split('').map(c => c + c).join('') : m[1];
    body.captionColor = '#' + h.toUpperCase();
  }
}

return [{ json: { body } }];

// What the viewer is actually looking at, per scene: AI GENERATED, ARCHIVAL
// FOOTAGE, ACTUAL FOOTAGE, SOURCE UNVERIFIED.
//
// A LOOKUP and nothing else. The classification is made once on the site
// (platform/lib/provenance.ts), stored on the scene (db/009) and emitted by
// hov.at_scene as one `Provenance` object already in the render's own shape.
// Nothing is decided here, and that is the point: a render path that
// re-derived provenance could disagree with the record the producer approved,
// on the one overlay whose whole job is telling the truth about the picture.
//
// Its OWN node beside Caption Colour and Attach Motif Cards, for the same
// reason those are: Build Remotion Props is large and actively edited, and
// this needs nothing from it but the body it already produced.
const body = $json.body;

let opts = {};
try {
  opts = JSON.parse(($('Fetch Project Info').first().json.fields || {})['Editing Options'] || '{}') || {};
} catch (e) { opts = {}; }

// On unless refused, like every other overlay - and the absence matters more
// here than elsewhere: a film that says nothing about where its pictures came
// from reads as a claim that they are real.
//
// The switch owns the LABEL only. A credit a licence REQUIRES is drawn
// whatever it says, and the render decides that from the provenance itself.
body.showSourceWatermark = opts.sourceWatermark !== false;

// Provenance per scene, matched on the scene ID rather than on position:
// Prepare Clips DROPS every scene with no final clip, so the index the
// database row sits at and the index the render draws part company the moment
// one clip is missing. Same anchor rule as Attach Motif Cards.
const byId = new Map();
try {
  for (const it of $('Fetch Approved Scenes').all()) {
    const p = (it.json.fields || {})['Provenance'];
    if (it.json.id != null && p) byId.set(it.json.id, p);
  }
} catch (e) {}

const clips = $('Prepare Clips').all();
let labelled = 0;
(body.scenes || []).forEach((s, i) => {
  const clip = clips[i];
  const p = clip ? byId.get(clip.json.id) : null;
  // Absent means db/009 has not been applied yet, or the row predates it. The
  // render draws nothing for a scene with no provenance, which is the right
  // direction for a label about truthfulness: silence rather than a guess.
  if (p) { s.provenance = p; labelled++; }
});
console.log('provenance on ' + labelled + '/' + (body.scenes || []).length + ' scenes, watermark ' + (body.showSourceWatermark ? 'on' : 'off'));

return [{ json: { body } }];
